import unittest,re
from tools.kjv_archive import load_register,read
class CorinthiansGiftsBoastingTests(unittest.TestCase):
 def test_gifts_and_foolish_boasting(self):
  prior,_=load_register('0.10-kjv.244');lang,manifest=load_register('0.10-kjv.245')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('2-corinthians-'):c for c in read(lang.folder/'corinthians-gifts-and-foolish-boasting-cases.json')};self.assertEqual(len(cases),66)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'9:1': ['saint:pl serve:ev', 'more than need'], '9:2': ['kjv_forward_eager_corinthians:ev', 'kjv_achaia_acts year ago ready', 'your/kjv_zeal very many'], '9:3': ['i brother:pl send:perf', 'ourone/boast:ev of you', 'as i say:pa you ready'], '9:4': ['if kjv_macedonia_acts person:pl with i', 'wesg that wesg you say:neg:pr', 'shame:adj be:should'], '9:5': ['before to you go:should', 'of which you before inform:psv:pa', 'as kjv_bounty and not as kjv_covetousness'], '9:6': ['little:adv kjv_sow:pr', 'little:adv reap:fu', 'generous:adv kjv_sow:pr', 'generous:adv reap:fu'], '9:7': ['each man', 'his/heart purpose:pr', 'not unwillingly nor of necessity', 'cheer:adj give:ag'], '9:8': ['all grace', 'always all enough:ev in all thing:pl', 'each good work'], '9:9': ['wide:adv disperse:perf', 'to poor:pl give:perf', 'his/kjv_righteousness for ever'], '9:10': ['seed to kjv_sow:ag', 'bread provide:opt', 'seed kjv_multiply:caus:opt', 'kjv_righteousness fruit:pl increase:opt'], '9:11': ['all generous:ev', 'through wesg thanks give:ev'], '9:12': ['not only saint:pl lack', 'many thanks give:ev:pl to god'], '9:13': ['this service proof', 'profess:psv:adj kjv_subject_authority_romans:psv:ev', 'to they and to all man:pl'], '9:14': ['their/prayer for you', 'exceed:cv grace of god in you'], '9:15': ['his/gift which speak:neg:can'], '10:1': ['i kjv_paul_acts myself', 'kjv_meek_disposition:ev and gentleness', 'presence among you base', 'absence be:cv towards you bold'], '10:2': ['some who of wesg as if according_to flesh walk:pr', 'bold be:neg:may'], '10:3': ['in flesh walk:pr', 'according_to flesh war:neg:pr'], '10:4': ['ourone/war:ev weapon:pl', 'flesh:adj be:neg:pr', 'through god strong', 'kjv_stronghold:pl down pull:ev'], '10:5': ['kjv_imaginations_argument_corinthians:pl', 'each high thing', 'each thought', 'into kjv_captivity'], '10:6': ['when your/obedience complete:psv:pr', 'all disobey:ev revenge:inf'], '10:7': ['look:pr:q', 'as he of kjv_christ_title', 'wesg of kjv_christ_title'], '10:8': ['ourone/authority', 'for kjv_edify_romans:ev and not for your/destroy:ev', 'i shame:adj be:neg:should'], '10:9': ['as if i by letter:pl', 'seem:neg:may'], '10:10': ['they say:pr', 'his/body:adj presence weak', 'his/speech contemptible'], '10:11': ['when absence', 'in deed when present', 'be:fu'], '10:12': ['ourselves into group', 'dare:neg:pr', 'themselves by themselves measure:cv', 'wise be:neg:pr'], '10:13': ['beyond ourone/measure boast:neg:fu', 'kjv_rule_scope_corinthians', 'god to wesg distribute:perf', 'even to you reach:inf'], '10:14': ['beyond ourone/measure ourselves stretch:neg:pr', 'as though to you reach:neg:pa', 'even as far as to you come:perf'], '10:15': ['other man:pl labour:pl', 'when your/faith increase:psv:pr', 'ourone/kjv_rule_scope_corinthians'], '10:16': ['region:pl beyond you', 'another man kjv_line_sphere_corinthians', 'ourone/hand ready'], '10:17': ['in kjv_lord glory:opt'], '10:18': ['not he who himself commend:pr', 'whom kjv_lord commend:pr'], '11:1': ['god grant:opt', 'my/folly little endure:can', 'with i endure:imp'], '11:2': ['god:adj jealous:ev', 'one_num husband', 'chaste virgin to kjv_christ_title'], '11:3': ['serpent kjv_eve:a', 'your/mind:pl', 'kjv_simplicity_integrity_corinthians'], '11:4': ['another kjv_jesus_matthew', 'another spirit', 'another kjv_gospel', 'with he well endure:may'], '11:5': ['very most chief kjv_apostle:pl', 'at all be:neg:pa'], '11:6': ['in speech kjv_rude_speech_corinthians', 'in knowledge not so', 'wesg among you in all thing:pl'], '11:7': ['myself lower:cv', 'you kjv_exalt:psv:may', 'kjv_freely_gift_romans'], '11:8': ['other kjv_church_assembly:pl rob:pa', 'kjv_wages:pl', 'to you service'], '11:9': ['and lack:pa', 'no man burden', 'from kjv_macedonia_acts', 'keep:perf', 'keep:fu'], '11:10': ['no man in kjv_achaia_acts region:pl', 'i:a stop:fu'], '11:11': ['why:q', 'love:neg:pr:q', 'god know:pr'], '11:12': ['what i do:pr that i do:fu', 'occasion cut:inf', 'even as wesg'], '11:13': ['false kjv_apostle:pl', 'deceive:adj work:ag:pl', 'themselves into kjv_christ_title kjv_apostle:pl transform:cv'], '11:14': ['kjv_satan_temptation himself', 'light angel transform:psv:pr'], '11:15': ['if his/serve:ag:pl', 'as kjv_righteousness serve:ag:pl', 'end according_to their/work:pl'], '11:16': ['let no man i:a fool think:opt', 'if otherwise yet as fool', 'little boast:may'], '11:17': ['not according_to kjv_lord', 'as it be:pa fool:adv', 'confidence of boast:ev'], '11:18': ['many according_to flesh glory:pr', 'i also glory:fu'], '11:19': ['fool:pl gladly endure:pr', 'you yourselves wise'], '11:20': ['into bondage', 'devour:pr', 'from you take:pr', 'himself kjv_exalt:pr', 'on face you:a strike:pr'], '11:21': ['as though wesg weak be:pp', 'i fool:adv speak:pr', 'i also bold'], '11:22': ['kjv_hebrew:pl', 'kjv_israel person:pl', 'kjv_abraham kjv_seedline'], '11:23': ['i as fool speak:pr', 'labour:pl', 'kjv_stripe_blow:pl above measure', 'prison:pl more often', 'death:pl often'], '11:24': ['five time:pl', 'three+twelve and four kjv_stripe_blow:pl except one_num'], '11:25': ['three time:pl i with rod:pl', 'one_num time i stone:psv:pa', 'three time:pl i kjv_shipwreck_corinthians', 'one_num night and one_num day'], '11:26': ['water:pl', 'rob:ag:pl', 'my/own country person:pl', 'kjv_gentile:pl', 'in city', 'kjv_wilderness', 'in sea', 'false brother:pl'], '11:27': ['weary:ev and pain:ev', 'watch:ev:pl often', 'hunger and thirst', 'kjv_fast:pl often', 'cold and kjv_nakedness'], '11:28': ['besides those thing:pl', 'daily', 'all kjv_church_assembly:pl kjv_care_concern_corinthians'], '11:29': ['i weak be:neg:pr:q', 'kjv_stumble:caus:psv:pr', 'i burn:neg:pr:q'], '11:30': ['if i glory:must', 'my/infirmity:pl', 'glory:fu'], '11:31': ['father of ourone/lord', 'for ever bless:psv:adj', 'i false speak:neg:pr'], '11:32': ['under kjv_aretas_corinthians king', 'with kjv_garrison', 'i:a seize:inf'], '11:33': ['through window in kjv_basket by wall', 'i lower:psv:pa', 'his/hand:pl escape:pa']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('not unwillingly nor of necessity',cases['9-7']['analysis'])
  self.assertIn('all enough:ev in all thing:pl',cases['9-8']['analysis'])
  self.assertIn('in flesh walk:pr',cases['10-3']['analysis'])
  self.assertIn('according_to flesh war:neg:pr',cases['10-3']['analysis'])
  self.assertIn('kjv_rule_scope_corinthians',cases['10-13']['analysis'])
  self.assertIn('one_num husband',cases['11-2']['analysis'])
  self.assertEqual(cases['11-4']['analysis'].count('another'),3)
  self.assertIn('not according_to kjv_lord',cases['11-17']['analysis'])
  self.assertEqual(cases['11-20']['analysis'].count('if man'),5)
  self.assertEqual(cases['11-22']['analysis'].count('so i be:pr'),3)
  self.assertIn('five time:pl i three+twelve and four kjv_stripe_blow:pl except one_num',cases['11-24']['analysis'])
  self.assertIn('three time:pl i kjv_shipwreck_corinthians',cases['11-25']['analysis'])
  self.assertIn('one_num night and one_num day',cases['11-25']['analysis'])
  self.assertIn('in kjv_basket by wall',cases['11-33']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),6)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
